async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${apiUrl}${path}`, { ...init, cache: "no-store" });
  const payload = await response.json().catch(() => ({})) as T & { error?: string };
  if (!response.ok) throw new Error(payload.error ?? "请求失败");
  return payload;
}

function formatDate(value?: string | null): string { if (!value) return "—"; return new Intl.DateTimeFormat("zh-CN", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(value)); }
function formatBytes(value: number): string { if (value < 1024) return `${value} B`; if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`; return `${(value / 1024 / 1024).toFixed(1)} MB`; }
function formatValue(value: Cell): string { if (value === null || value === undefined) return "—"; if (typeof value === "number") return new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 2 }).format(value); return String(value); }
function chartTypeName(type: FlintSpec["chartSpec"]["chartType"]): string { return type === "Bar Chart" ? "Bar" : type === "Area Chart" ? "Area" : "Line"; }
function rowsForEvidence(evidence: EvidenceRecord | null): Array<Record<string, Cell>> { if (evidence?.job?.previewData?.rows) return evidence.job.previewData.rows; return evidence?.revision.flintSpec.data.values ?? []; }

function InteractiveChart({ rows, spec }: { rows: Array<Record<string, Cell>>; spec: FlintSpec }) {
  const [activePoint, setActivePoint] = useState<string | null>(null);
  const xField = spec.chartSpec.encodings.x?.field;
  const yField = spec.chartSpec.encodings.y?.field;
  const colorField = spec.chartSpec.encodings.color?.field;
  const chartRows = useMemo(() => rows.filter((row) => xField && yField && typeof row[yField] === "number"), [rows, xField, yField]);
  const xValues = useMemo(() => [...new Set(chartRows.map((row) => String(xField ? row[xField] ?? "" : "")))], [chartRows, xField]);
  const seriesValues = useMemo(() => colorField ? [...new Set(chartRows.map((row) => String(row[colorField] ?? "")))] : [""], [chartRows, colorField]);
  const values = chartRows.map((row) => Number(yField ? row[yField] : 0));
  if (!xField || !yField || chartRows.length === 0) return <div className="chart-empty">校验通过，但没有可绘制的数值行。</div>;
  const width = 900; const height = 360; const left = 70; const top = 28; const right = 22; const bottom = 56; const plotWidth = width - left - right; const plotHeight = height - top - bottom; const min = Math.min(...values, 0); const max = Math.max(...values, 0); const range = max - min || 1; const colors = ["#1f1d3d", "#ff3d8b", "#1ea64a", "#000000"]; const xPosition = (value: string) => xValues.length <= 1 ? plotWidth / 2 : xValues.indexOf(value) * plotWidth / (xValues.length - 1); const yPosition = (value: number) => plotHeight - ((value - min) / range) * plotHeight; const baseline = top + yPosition(Math.min(0, max));
  return <div className="chart-visual" aria-label={`${spec.chartSpec.title}图表预览`}><svg className="chart-svg" viewBox={`0 0 ${width} ${height}`} role="img"><line x1={left} y1={top + plotHeight} x2={left + plotWidth} y2={top + plotHeight} className="chart-axis" /><line x1={left} y1={top} x2={left} y2={top + plotHeight} className="chart-axis" />{[0, 0.33, 0.66, 1].map((step) => <g key={step}><line x1={left} y1={top + plotHeight * step} x2={left + plotWidth} y2={top + plotHeight * step} className="chart-grid" /><text x={left - 10} y={top + plotHeight * step + 4} textAnchor="end">{formatValue(max - (max - min) * step)}</text></g>)}{xValues.map((value) => <text key={value} x={left + xPosition(value)} y={top + plotHeight + 25} textAnchor="middle">{value}</text>)}{seriesValues.map((seriesValue, seriesIndex) => { const points = chartRows.filter((row) => !colorField || String(row[colorField] ?? "") === seriesValue).sort((a, b) => xValues.indexOf(String(a[xField] ?? "")) - xValues.indexOf(String(b[xField] ?? ""))); const path = points.map((row, index) => `${index === 0 ? "M" : "L"}${left + xPosition(String(row[xField] ?? ""))},${top + yPosition(Number(row[yField]))}`).join(" "); const areaPath = `${path} L ${left + xPosition(String(points[points.length - 1]?.[xField] ?? ""))},${baseline} L ${left + xPosition(String(points[0]?.[xField] ?? ""))},${baseline} Z`; return <g key={seriesValue || "default"}>{spec.chartSpec.chartType === "Area Chart" && <path d={areaPath} fill={colors[seriesIndex % colors.length]} opacity="0.12" />}{spec.chartSpec.chartType === "Bar Chart" ? points.map((row, index) => { const value = Number(row[yField]); const slot = plotWidth / Math.max(xValues.length * seriesValues.length, 1); const barWidth = Math.max(8, slot * 0.68); const x = left + xPosition(String(row[xField] ?? "")) - ((seriesValues.length - 1) * barWidth) / 2 + seriesIndex * barWidth; const y = top + yPosition(Math.max(value, 0)); const key = `${seriesValue}-${index}`; return <rect key={key} tabIndex={0} role="button" aria-label={`${String(row[xField] ?? "")}: ${formatValue(row[yField])}`} x={x - barWidth / 2} y={Math.min(y, baseline)} width={Math.max(3, barWidth - 2)} height={Math.max(2, Math.abs(baseline - y))} fill={colors[seriesIndex % colors.length]} opacity={activePoint === key ? 1 : 0.78} onMouseEnter={() => setActivePoint(key)} onFocus={() => setActivePoint(key)} />; }) : <><path d={path} fill="none" stroke={colors[seriesIndex % colors.length]} strokeWidth="3" />{points.map((row, index) => { const key = `${seriesValue}-${index}`; return <circle key={key} tabIndex={0} role="button" aria-label={`${String(row[xField] ?? "")}: ${formatValue(row[yField])}`} cx={left + xPosition(String(row[xField] ?? ""))} cy={top + yPosition(Number(row[yField]))} r={activePoint === key ? 7 : 4.5} fill={colors[seriesIndex % colors.length]} onMouseEnter={() => setActivePoint(key)} onFocus={() => setActivePoint(key)} />; })}</>}</g>; })}</svg><div className="chart-readout">{activePoint ? "已聚焦数据点" : "悬停或聚焦数据点查看数值"}</div></div>;
}

function Pipeline({ job }: { job: GenerationJob }) { const currentIndex = pipelineStages.indexOf(job.status); return <div className="pipeline" aria-label="Generation Cycle 状态">{pipelineStages.map((stage, index) => <div className={`${index < currentIndex || job.status === "succeeded" ? "done" : ""} ${stage === job.status ? "current" : ""}`} key={stage}><span>{index + 1}</span><strong>{statusLabels[stage]}</strong></div>)}</div>; }

export default function Home() {
  const [workspace, setWorkspace] = useState<Workspace | null>(null); const [projects, setProjects] = useState<Project[]>([]); const [projectId, setProjectId] = useState<string | null>(null); const [conversations, setConversations] = useState<Conversation[]>([]); const [conversationId, setConversationId] = useState<string | null>(null); const [messages, setMessages] = useState<ConversationMessage[]>([]); const [assets, setAssets] = useState<Asset[]>([]); const [selectedAssetId, setSelectedAssetId] = useState<string | null>(null); const [metric, setMetric] = useState<MetricDefinition | null>(null); const [brief, setBrief] = useState<AnalysisBrief | null>(null); const [memory, setMemory] = useState<MemoryContext>({ project: [], workspace: [], conflicts: [] }); const [evidence, setEvidence] = useState<EvidenceRecord[]>([]); const [job, setJob] = useState<GenerationJob | null>(null); const [theme, setTheme] = useState("economist"); const [composer, setComposer] = useState(""); const [projectName, setProjectName] = useState(""); const [metricForm, setMetricForm] = useState({ name: "销售额", meaning: "客户订单的销售金额总和。", formula: "sum(销售额)", unit: "人民币", timeRule: "按自然月聚合", filterRule: "" }); const [editor, setEditor] = useState({ title: "", chartType: "Line Chart" as FlintSpec["chartSpec"]["chartType"], xField: "", yField: "", seriesField: "" }); const [projectMenuOpen, setProjectMenuOpen] = useState(false); const [conversationMenuOpen, setConversationMenuOpen] = useState(false); const [showProjectModal, setShowProjectModal] = useState(false); const [showMetricModal, setShowMetricModal] = useState(false); const [showEditor, setShowEditor] = useState(false); const [showTrace, setShowTrace] = useState(false); const [isBooting, setIsBooting] = useState(true); const [isLoadingProject, setIsLoadingProject] = useState(false); const [isSending, setIsSending] = useState(false); const [isUploading, setIsUploading] = useState(false); const [isGenerating, setIsGenerating] = useState(false); const [isSavingEditor, setIsSavingEditor] = useState(false); const [notice, setNotice] = useState<string | null>(null); const [error, setError] = useState<string | null>(null); const fileInputRef = useRef<HTMLInputElement>(null);

  const project = useMemo(() => projects.find((item) => item.id === projectId) ?? null, [projects, projectId]); const selectedAsset = useMemo(() => assets.find((asset) => asset.id === selectedAssetId) ?? assets[0] ?? null, [assets, selectedAssetId]); const selectedConversation = useMemo(() => conversations.find((item) => item.id === conversationId) ?? null, [conversations, conversationId]); const activeEvidence = useMemo(() => evidence.find((item) => item.block.conversationId === conversationId) ?? null, [evidence, conversationId]); const activeRevision = activeEvidence?.revision ?? null; const activeSpec = activeEvidence?.revision.flintSpec ?? job?.flintSpec ?? null; const activeRows = rowsForEvidence(activeEvidence); const qualityWarnings = useMemo(() => selectedAsset?.latestSnapshot?.schema.filter((column) => column.nullCount > 0).map((column) => ({ code: "NULL_VALUES", message: `${column.name} 有 ${column.nullCount.toLocaleString()} 个缺失值，生成未将缺失月份静默补为 0。`, severity: "warning" as const, field: column.name })) ?? [], [selectedAsset]); const isJobActive = Boolean(job && !["succeeded", "failed"].includes(job.status)); const canGenerate = Boolean(projectId && conversationId && selectedAsset?.status === "ready" && selectedAsset.latestSnapshot && metric?.status === "confirmed" && !isJobActive && !isGenerating);

  const loadProjects = useCallback(async () => { const payload = await apiFetch<{ workspace: Workspace | null; projects: Project[] }>("/api/v1/projects", { headers: devHeaders }); setWorkspace(payload.workspace); setProjects(payload.projects); return payload; }, []);
  const loadEvidence = useCallback(async (nextProjectId: string) => { const payload = await apiFetch<{ evidence: EvidenceRecord[] }>(`/api/v1/projects/${nextProjectId}/evidence-blocks`, { headers: devHeaders }); setEvidence(payload.evidence); return payload.evidence; }, []);
  const loadConversations = useCallback(async (nextProjectId: string) => { const payload = await apiFetch<{ conversations: Conversation[] }>(`/api/v1/projects/${nextProjectId}/conversations`, { headers: devHeaders }); setConversations(payload.conversations); return payload.conversations; }, []);

  useEffect(() => { let cancelled = false; async function boot() { try { setIsBooting(true); const bootstrap = await apiFetch<{ workspace: Workspace; project: Project }>("/api/v1/dev/bootstrap", { method: "POST", headers: jsonHeaders, body: "{}" }); const payload = await loadProjects(); if (cancelled) return; const remembered = window.localStorage.getItem("langreport-project-id"); setProjectId(payload.projects.find((item) => item.id === remembered)?.id ?? bootstrap.project.id ?? payload.projects[0]?.id ?? null); } catch (bootError) { if (!cancelled) setError(bootError instanceof Error ? bootError.message : "无法连接 LangReport API"); } finally { if (!cancelled) setIsBooting(false); } } void boot(); return () => { cancelled = true; }; }, [loadProjects]);

  useEffect(() => { if (!projectId) return; window.localStorage.setItem("langreport-project-id", projectId); let cancelled = false; async function loadProject() { try { setIsLoadingProject(true); setAssets([]); setConversations([]); setMessages([]); setEvidence([]); setMetric(null); setBrief(null); setJob(null); const [assetPayload, conversationPayload, metricPayload, briefPayload, memoryPayload, evidencePayload, themePayload] = await Promise.all([apiFetch<{ assets: Asset[] }>(`/api/v1/projects/${projectId}/data-assets`, { headers: devHeaders }), apiFetch<{ conversations: Conversation[] }>(`/api/v1/projects/${projectId}/conversations`, { headers: devHeaders }), apiFetch<{ definition: MetricDefinition | null }>(`/api/v1/projects/${projectId}/metric-definition`, { headers: devHeaders }), apiFetch<{ brief: AnalysisBrief | null }>(`/api/v1/projects/${projectId}/analysis-brief`, { headers: devHeaders }), apiFetch<{ memory: MemoryContext }>(`/api/v1/projects/${projectId}/memories`, { headers: devHeaders }), apiFetch<{ evidence: EvidenceRecord[] }>(`/api/v1/projects/${projectId}/evidence-blocks`, { headers: devHeaders }), apiFetch<{ theme: { preset: string } }>(`/api/v1/projects/${projectId}/theme`, { headers: devHeaders })]); if (cancelled) return; setAssets(assetPayload.assets); setSelectedAssetId(assetPayload.assets[0]?.id ?? null); setConversations(conversationPayload.conversations); setMetric(metricPayload.definition); setBrief(briefPayload.brief); setMemory(memoryPayload.memory); setEvidence(evidencePayload.evidence); setTheme(themePayload.theme.preset); const rememberedConversation = window.localStorage.getItem(`langreport-conversation-${projectId}`); setConversationId(conversationPayload.conversations.find((item) => item.id === rememberedConversation)?.id ?? conversationPayload.conversations[0]?.id ?? null); const latest = evidencePayload.evidence[0]; if (latest?.job && !["succeeded", "failed"].includes(latest.job.status)) setJob(latest.job); } catch (loadError) { if (!cancelled) setError(loadError instanceof Error ? loadError.message : "无法读取 Project 数据"); } finally { if (!cancelled) setIsLoadingProject(false); } } void loadProject(); return () => { cancelled = true; }; }, [projectId]);

  useEffect(() => { if (!conversationId) { setMessages([]); return; } window.localStorage.setItem(`langreport-conversation-${projectId}`, conversationId); let cancelled = false; void apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { headers: devHeaders }).then((payload) => { if (!cancelled) setMessages(payload.messages); }).catch((loadError) => { if (!cancelled) setError(loadError instanceof Error ? loadError.message : "无法读取 Conversation"); }); return () => { cancelled = true; }; }, [conversationId, projectId]);

  useEffect(() => { if (job && job.conversationId !== conversationId) setJob(null); }, [conversationId, job]);

  useEffect(() => { if (!job?.id || !isJobActive) return; let cancelled = false; const poll = async () => { try { const payload = await apiFetch<{ job: GenerationJob; revision: GenerationJob["revision"] }>(`/api/v1/generation-jobs/${job.id}`, { headers: devHeaders }); if (cancelled) return; setJob({ ...payload.job, revision: payload.revision }); if (payload.job.status === "succeeded" && projectId) { await Promise.all([loadEvidence(projectId), loadConversations(projectId)]); if (conversationId) { const messagePayload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { headers: devHeaders }); if (!cancelled) setMessages(messagePayload.messages); } setNotice(payload.job.operation === "edit" ? "新的 Draft Chart Revision 已保存。" : "Draft Evidence Block 已生成，所有来源和校验信息已绑定。"); } } catch (pollError) { if (!cancelled) setError(pollError instanceof Error ? pollError.message : "无法读取生成状态"); } }; void poll(); const interval = window.setInterval(() => { void poll(); }, 900); return () => { cancelled = true; window.clearInterval(interval); }; }, [conversationId, isJobActive, job?.id, loadConversations, loadEvidence, projectId]);

  async function createConversation(): Promise<string | null> { if (!projectId) return null; try { const payload = await apiFetch<{ conversation: Conversation }>(`/api/v1/projects/${projectId}/conversations`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ title: "新的分析对话" }) }); setConversations((current) => [payload.conversation, ...current]); setConversationId(payload.conversation.id); return payload.conversation.id; } catch (createError) { setError(createError instanceof Error ? createError.message : "无法创建 Conversation"); return null; } }
  async function createProject() { if (!projectName.trim()) return; try { const payload = await apiFetch<{ project: Project }>("/api/v1/projects", { method: "POST", headers: jsonHeaders, body: JSON.stringify({ name: projectName.trim() }) }); const nextProjects = await loadProjects(); setProjects(nextProjects.projects); setProjectId(payload.project.id); setProjectName(""); setShowProjectModal(false); setNotice(`已创建 Project「${payload.project.name}」。`); } catch (createError) { setError(createError instanceof Error ? createError.message : "无法创建 Project"); } }
  async function sendMessage() { const content = composer.trim(); if (!content || !projectId || isSending) return; setIsSending(true); setError(null); try { const nextConversationId = conversationId ?? await createConversation(); if (!nextConversationId) return; const payload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${nextConversationId}/messages`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ content }) }); setMessages((current) => [...current, ...payload.messages]); setComposer(""); setConversations(await loadConversations(projectId)); } catch (sendError) { setError(sendError instanceof Error ? sendError.message : "消息保存失败"); } finally { setIsSending(false); } }
  async function confirmMetric() { if (!projectId || !metricForm.name.trim()) return; try { const payload = await apiFetch<{ definition: MetricDefinition }>(`/api/v1/projects/${projectId}/metric-definitions`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ ...metricForm, filterRule: metricForm.filterRule || undefined, conversationId: conversationId ?? undefined }) }); setMetric(payload.definition); setShowMetricModal(false); setNotice(`已确认「${payload.definition.name}」口径 v${payload.definition.version}。`); if (conversationId) { const messagePayload = await apiFetch<{ messages: ConversationMessage[] }>(`/api/v1/conversations/${conversationId}/messages`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ content: `确认指标口径：${payload.definition.name} = ${payload.definition.formula}`, assistantContent: `已确认 Metric Definition v${payload.definition.version}。后续生成会使用这个口径，不会自动写入其他 Project。` }) }); setMessages((current) => [...current, ...messagePayload.messages]); } } catch (metricError) { setError(metricError instanceof Error ? metricError.message : "无法保存指标口径"); } }
  async function uploadFile(file: File) { if (!projectId) return; setIsUploading(true); setError(null); try { const formData = new FormData(); formData.append("file", file); const payload = await apiFetch<{ asset: Asset }>(`/api/v1/projects/${projectId}/data-assets/upload`, { method: "POST", headers: devHeaders, body: formData }); setAssets((current) => [payload.asset, ...current]); setSelectedAssetId(payload.asset.id); setNotice(`已生成 Data Snapshot v${payload.asset.latestSnapshot?.version ?? 1}。原有快照不会被覆盖。`); } catch (uploadError) { setError(uploadError instanceof Error ? uploadError.message : "文件上传失败"); } finally { setIsUploading(false); if (fileInputRef.current) fileInputRef.current.value = ""; } }
  async function pasteData(content: string, name: string) { if (!projectId || !content.trim()) return; setIsUploading(true); setError(null); try { const payload = await apiFetch<{ asset: Asset }>(`/api/v1/projects/${projectId}/data-assets/paste`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ name, content }) }); setAssets((current) => [payload.asset, ...current]); setSelectedAssetId(payload.asset.id); setNotice(`已保存「${payload.asset.name}」并创建 Data Snapshot。`); } catch (pasteError) { setError(pasteError instanceof Error ? pasteError.message : "粘贴数据失败"); } finally { setIsUploading(false); } }
  async function generateEvidence() { if (!projectId || !selectedAsset?.latestSnapshot || !metric || selectedAsset.status !== "ready" || isJobActive || isGenerating) return; setIsGenerating(true); setError(null); setNotice(null); try { const nextConversationId = conversationId ?? await createConversation(); if (!nextConversationId) return; const prompt = composer.trim() || "按月份展示各区域销售额和同比变化，并指出数据质量限制"; const payload = await apiFetch<{ job: GenerationJob }>(`/api/v1/projects/${projectId}/generation-jobs`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ conversationId: nextConversationId, dataAssetId: selectedAsset.id, prompt, renderer: "vega-lite" }) }); setJob({ ...payload.job, revision: null }); setComposer(""); } catch (generationError) { setError(generationError instanceof Error ? generationError.message : "无法创建 Generation Cycle"); } finally { setIsGenerating(false); } }
  function openEditor() { if (!activeEvidence || activeRevision?.status === "approved" || activeRevision?.status === "archived") return; const spec = activeEvidence.revision.flintSpec; setEditor({ title: spec.chartSpec.title, chartType: spec.chartSpec.chartType, xField: spec.chartSpec.encodings.x?.field ?? "", yField: spec.chartSpec.encodings.y?.field ?? "", seriesField: spec.chartSpec.encodings.color?.field ?? "" }); setShowEditor(true); }
  async function saveEditor() { if (!activeEvidence || !activeRevision || !editor.title.trim() || isSavingEditor) return; setIsSavingEditor(true); setError(null); try { const encodings: FlintSpec["chartSpec"]["encodings"] = { x: { field: editor.xField, type: activeEvidence.revision.flintSpec.chartSpec.encodings.x?.type ?? "nominal" }, y: { field: editor.yField, type: "quantitative" } }; if (editor.seriesField) encodings.color = { field: editor.seriesField, type: "nominal" }; const payload = await apiFetch<{ job: GenerationJob }>(`/api/v1/chart-artifacts/${activeEvidence.artifact.id}/revisions`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ operation: "edit", baseRevisionId: activeRevision.id, patch: { title: editor.title.trim(), chartType: editor.chartType, encodings } }) }); setJob({ ...payload.job, revision: null }); setShowEditor(false); setNotice("编辑任务已排队；完成后会创建新的 Draft Chart Revision。"); } catch (editError) { setError(editError instanceof Error ? editError.message : "无法创建新的 Revision"); } finally { setIsSavingEditor(false); } }
  async function transitionRevision(action: "submit" | "approve" | "request-changes") { if (!activeRevision) return; try { const payload = await apiFetch<{ revision: Revision }>(`/api/v1/chart-revisions/${activeRevision.id}/${action}`, { method: "POST", headers: jsonHeaders, body: JSON.stringify({ expectedStatus: activeRevision.status, note: action === "request-changes" ? "请补充图表说明或处理数据质量警告" : undefined }) }); setEvidence((current) => current.map((item) => item.revision.id === payload.revision.id ? { ...item, revision: payload.revision, block: { ...item.block, status: payload.revision.status } } : item)); setNotice(`Revision R${payload.revision.revision} 已更新为 ${revisionLabels[payload.revision.status]}`); } catch (transitionError) { setError(transitionError instanceof Error ? transitionError.message : "无法更新审核状态"); } }
  const availableFields = activeSpec ? Object.keys(activeSpec.data.values[0] ?? {}) : [];

  return <div className="app-shell" onClick={() => { setProjectMenuOpen(false); setConversationMenuOpen(false); }}>
    <header className="topbar" onClick={(event) => event.stopPropagation()}><div className="brand-lockup"><span className="brand-mark">L/</span><span className="brand-name">LangReport</span></div><div className="top-selectors"><div className="selector project-selector"><button type="button" className="selector-button" aria-expanded={projectMenuOpen} onClick={() => { setProjectMenuOpen((open) => !open); setConversationMenuOpen(false); }}><span className="selector-icon">P</span><span className="selector-copy"><span className="eyebrow">Project</span><strong>{project?.name ?? (isBooting ? "正在连接…" : "选择 Project")}</strong><small>{projects.length} 个咨询项目 · {workspace?.name ?? "Local Workspace"}</small></span><span className="selector-chevron">⌄</span></button>{projectMenuOpen && <div className="selector-menu"><span className="menu-kicker">Switch project</span>{projects.map((item) => <button type="button" key={item.id} className={`menu-item ${item.id === projectId ? "current" : ""}`} onClick={() => { setProjectId(item.id); setProjectMenuOpen(false); }}><strong>{item.name}</strong><small>{item.id === projectId ? "Active project" : "Consulting project"}</small></button>)}<button type="button" className="menu-create" onClick={() => { setShowProjectModal(true); setProjectMenuOpen(false); }}>＋ 新建 Project</button></div>}</div><div className="selector conversation-selector"><button type="button" className="selector-button" aria-expanded={conversationMenuOpen} onClick={() => { setConversationMenuOpen((open) => !open); setProjectMenuOpen(false); }}><span className="selector-icon">C</span><span className="selector-copy"><span className="eyebrow">Conversation history</span><strong>{selectedConversation?.title ?? "新的分析对话"}</strong><small>{conversations.length} 条对话 · {selectedConversation ? formatDate(selectedConversation.updatedAt) : "尚未开始"}</small></span><span className="selector-chevron">⌄</span></button>{conversationMenuOpen && <div className="selector-menu"><span className="menu-kicker">Switch conversation</span>{conversations.map((item) => <button type="button" key={item.id} className={`menu-item ${item.id === conversationId ? "current" : ""}`} onClick={() => { setConversationId(item.id); setConversationMenuOpen(false); }}><strong>{item.title}</strong><small>{formatDate(item.updatedAt)}</small></button>)}<button type="button" className="menu-create" onClick={() => { void createConversation(); setConversationMenuOpen(false); }}>＋ 新建 Conversation</button></div>}</div></div><div className="topbar-actions"><span className="connection-status"><i /> {error ? "attention" : "API ready"}</span><button type="button" className="icon-button" aria-label="帮助">?</button></div></header>
    <div className="workspace-grid">
      <aside className="history-rail" aria-label="Conversation history"><div className="rail-head"><div><div className="eyebrow">Project conversations</div><h2>对话历史</h2></div><button type="button" className="icon-button small-icon" aria-label="新建对话" onClick={() => void createConversation()}>＋</button></div><div className="history-list">{isLoadingProject ? <div className="rail-empty">正在载入 Project…</div> : conversations.length === 0 ? <div className="rail-empty"><strong>还没有对话</strong><small>从这里开始一个分析问题。</small></div> : conversations.map((item) => { const conversationEvidence = evidence.find((record) => record.block.conversationId === item.id); return <button type="button" key={item.id} className={`history-item ${item.id === conversationId ? "current" : ""}`} onClick={() => setConversationId(item.id)}><strong>{item.title}</strong><small>{conversationEvidence ? `R${conversationEvidence.revision.revision} · ${revisionLabels[conversationEvidence.revision.status]}` : "等待分析问题"}</small><div className="history-meta"><span>{formatDate(item.updatedAt)}</span><span>↗</span></div></button>; })}</div><div className="rail-divider" /><div className="eyebrow rail-context-title">Project context</div><div className="rail-context"><div><span>Data assets</span><strong>{assets.length.toString().padStart(2, "0")}</strong></div><div><span>Evidence blocks</span><strong>{evidence.length.toString().padStart(2, "0")}</strong></div><div><span>Metric</span><strong>{metric?.status === "confirmed" ? "OK" : "—"}</strong></div><div><span>Template</span><strong>{theme}</strong></div></div><p className="rail-footer">每个生成结果都会绑定当前 Project、Data Snapshot 和不可变 Revision。</p></aside>
      <main className="chat-main"><section className="chat-intro"><div><div className="eyebrow">VARIANT A / CHAT FIRST</div><h1>从问题开始，<br /><span>留下证据。</span></h1><p>在 Conversation 中澄清业务问题，LangReport 只生成一个可追溯的 Evidence Block；数据、口径和版本始终可以回查。</p></div><div className="intro-stamp"><strong>{project ? "CONSULTING PROJECT" : "CONNECTING"}</strong><span>{project ? "ONE CYCLE / ONE BLOCK" : "API"}</span></div></section>{error && <div className="alert error-alert" role="alert"><strong>需要处理</strong><span>{error}</span><button type="button" onClick={() => setError(null)}>关闭</button></div>}{notice && <div className="alert notice-alert" role="status"><span>{notice}</span><button type="button" onClick={() => setNotice(null)}>知道了</button></div>}
        <section className="conversation-panel" aria-label="多轮对话"><div className="message-list">{messages.length === 0 ? <div className="welcome-message"><span className="message-avatar ai-avatar">AI</span><div><div className="message-meta"><span>LangReport · context ready</span><time>now</time></div><div className="bubble"><strong>先告诉我你要回答的业务问题。</strong><p>你可以先导入 CSV 或使用示例数据，再确认指标口径。生成前我会展示 Data Snapshot 和待确认项。</p><div className="welcome-actions"><button type="button" className="text-pill" onClick={() => setComposer("按月份展示各区域销售额和同比变化，并指出数据质量限制")}>使用示例问题</button><button type="button" className="text-pill" onClick={() => setShowMetricModal(true)}>确认指标口径</button></div></div></div></div> : messages.map((message) => <div className={`message ${message.role === "user" ? "user-message" : "ai-message"}`} key={message.id}><span className={`message-avatar ${message.role === "user" ? "user-avatar" : "ai-avatar"}`}>{message.role === "user" ? "YL" : "AI"}</span><div className="message-content"><div className="message-meta"><span>{message.role === "user" ? "Y. Lin · 顾问" : "LangReport"}</span><time>{formatDate(message.createdAt)}</time></div><div className="bubble">{message.content}</div></div></div>)}{job && isJobActive && <div className="message ai-message"><span className="message-avatar ai-avatar">AI</span><div className="message-content"><div className="message-meta"><span>LangReport · Generation Cycle</span><time>now</time></div><div className="job-card"><div className="job-card-head"><div><strong>{statusLabels[job.status] ?? job.status}</strong><small>JOB {job.id.slice(0, 8).toUpperCase()} · one snapshot</small></div><span className="status-dot" /></div><Pipeline job={job} /></div></div></div>}{job?.status === "failed" && <div className="message ai-message"><span className="message-avatar warning-avatar">!</span><div className="message-content"><div className="message-meta"><span>LangReport · failed with explanation</span><time>now</time></div><div className="failure-card"><strong>{job.errorCode ?? "GENERATION_FAILED"}</strong><p>{job.errorMessage ?? "这次生成没有产生成功图表。"}</p><small>建议：检查数据字段、指标口径和时间范围后，创建一轮新的 Generation Cycle。</small></div></div></div>}{activeEvidence && <div className="message ai-message result-message"><span className="message-avatar ai-avatar">AI</span><div className="message-content"><div className="message-meta"><span>LangReport · Draft Evidence Block</span><time>{formatDate(activeEvidence.block.updatedAt)}</time></div><div className="result-card"><div className="result-card-head"><div><div className="eyebrow">EVIDENCE BLOCK / R{activeEvidence.revision.revision}</div><h2>{activeEvidence.block.title}</h2><p>1 chart artifact · 1 finding · {revisionLabels[activeEvidence.revision.status]}</p></div><span className={`result-status ${activeEvidence.revision.status}`}><i />{revisionLabels[activeEvidence.revision.status]}</span></div><div className="result-chart-wrap"><InteractiveChart rows={activeRows} spec={activeEvidence.revision.flintSpec} /></div><div className="finding"><span className="eyebrow">FINDING / HUMAN-REVIEWABLE</span><p>{activeEvidence.block.finding}</p></div><div className="result-source-row"><span>Snapshot <strong>{activeEvidence.block.snapshotId.slice(0, 8)}</strong></span><span>Metric <strong>{metric?.name ?? "已绑定口径"}</strong></span><span>Template <strong>{activeEvidence.revision.flintSpec.theme} · {activeEvidence.revision.flintSpec.themeVersion}</strong></span><span>Revision <strong>R{activeEvidence.revision.revision}</strong></span></div>{(qualityWarnings.length > 0 || activeEvidence.block.qualityWarnings.length > 0) && <div className="quality-warning" role="status"><strong>数据质量提示</strong><span>{[...qualityWarnings, ...activeEvidence.block.qualityWarnings].slice(0, 3).map((warning) => warning.message).join("；")}</span></div>}<div className="result-actions"><button type="button" className="primary-button" onClick={openEditor} disabled={activeEvidence.revision.status === "approved" || activeEvidence.revision.status === "archived"}>编辑图表 <span>↗</span></button><button type="button" className="secondary-button" onClick={() => setShowTrace((open) => !open)}>{showTrace ? "收起依据" : "查看依据"}</button>{activeEvidence.revision.status === "draft" && <button type="button" className="secondary-button" onClick={() => void transitionRevision("submit")}>提交审核</button>}{activeEvidence.revision.status === "in_review" && <><button type="button" className="primary-button" onClick={() => void transitionRevision("approve")}>批准 Revision <span>↗</span></button><button type="button" className="secondary-button" onClick={() => void transitionRevision("request-changes")}>要求修改</button></>}</div>{showTrace && <div className="trace-grid"><div><span>TRANSFORM PLAN</span><strong>{activeEvidence.revision.transformPlan.steps?.length ?? 0} steps</strong><small>{activeEvidence.revision.transformPlan.rationale ?? "受限变换计划已固化"}</small></div><div><span>FIELD LINEAGE</span><strong>{activeEvidence.revision.fieldLineage.length} outputs</strong><small>{activeEvidence.revision.fieldLineage.map((line) => `${line.outputColumn} ← ${line.sourceColumns.join(" + ")}`).join(" · ") || "—"}</small></div><div><span>VALIDATION</span><strong>{activeEvidence.revision.validation.valid ? "4 / 4 passed" : "failed"}</strong><small>{activeEvidence.revision.validation.issues.length ? activeEvidence.revision.validation.issues.map((issue) => issue.message).join("；") : "schema · semantics · fields · visual"}</small></div><div><span>IMMUTABILITY</span><strong>Snapshot fixed</strong><small>编辑只创建新 Revision，不覆盖历史版本。</small></div></div>}</div></div></div>}{activeEvidence?.revision && activeEvidence.revision.status === "approved" && <div className="approved-note">这是已批准版本；编辑入口保持只读。</div>}</div><div className="composer-wrap"><div className="composer"><textarea value={composer} onChange={(event) => setComposer(event.target.value)} onKeyDown={(event) => { if ((event.metaKey || event.ctrlKey) && event.key === "Enter") void sendMessage(); }} aria-label="继续 Conversation" placeholder="继续问一个问题，或描述你要生成的证据……" disabled={isSending || isJobActive} /><div className="composer-bottom"><div className="composer-meta"><span>project: {project?.name ?? "—"}</span><span>{selectedAsset?.latestSnapshot ? `snapshot v${selectedAsset.latestSnapshot.version}` : "no snapshot"}</span><span>{metric?.status === "confirmed" ? "metric confirmed" : "metric needs confirmation"}</span></div><div className="composer-actions"><button type="button" className="secondary-button composer-send" onClick={() => void sendMessage()} disabled={!composer.trim() || isSending || isJobActive}>{isSending ? "保存中…" : "发送"}</button><button type="button" className="primary-button composer-generate" onClick={() => void generateEvidence()} disabled={!canGenerate}>{isGenerating ? "创建中…" : isJobActive ? `${statusLabels[job?.status ?? "queued"]}…` : "生成证据 ↗"}</button></div></div></div></div></section>
      </main>
      <aside className="context-rail" aria-label="Expandable project context"><div className="context-title"><div className="eyebrow">Project context</div><h2>按需查看</h2><p>把数据、口径和版本收在对话旁边。</p></div><details open><summary><strong>当前数据</strong><span>{selectedAsset ? "−" : "＋"}</span></summary><div className="context-content">{selectedAsset?.latestSnapshot ? <><div className="context-row"><span>Asset</span><strong>{selectedAsset.name}</strong></div><div className="context-row"><span>Snapshot</span><strong>v{selectedAsset.latestSnapshot.version} · {selectedAsset.latestSnapshot.rowCount.toLocaleString()} rows</strong></div><div className="context-row"><span>Fields</span><strong>{selectedAsset.latestSnapshot.columnCount}</strong></div><div className="context-quality">{qualityWarnings.length ? `${qualityWarnings.length} 个字段存在缺失值` : "未发现字段缺失"}</div><div className="context-data-list">{selectedAsset.latestSnapshot.schema.slice(0, 6).map((column) => <div key={column.name}><span>{column.name}</span><small>{column.inferredType} · {column.distinctCount} unique</small></div>)}</div></> : <div className="context-empty">还没有 Data Snapshot。<button type="button" onClick={() => fileInputRef.current?.click()}>导入 CSV</button></div>}</div></details><details><summary><strong>Brief &amp; metric</strong><span>{metric?.status === "confirmed" ? "✓" : "＋"}</span></summary><div className="context-content">{brief ? <div className="context-note">{brief.businessQuestion}</div> : <div className="context-note">生成后会固定本轮 Analysis Brief。</div>}{metric ? <><div className="context-row"><span>Metric</span><strong>{metric.name} · v{metric.version}</strong></div><div className="context-note">{metric.formula} · {metric.unit} · {metric.timeRule}</div></> : <button type="button" className="context-cta" onClick={() => setShowMetricModal(true)}>确认指标口径 <span>↗</span></button>}</div></details><details><summary><strong>Project memory</strong><span>{memory.project.length + memory.workspace.length ? "✓" : "＋"}</span></summary><div className="context-content">{memory.project.length + memory.workspace.length === 0 ? <div className="context-empty">暂时没有已确认的 Project Memory。模型候选不会自动变成长期事实。</div> : [...memory.project, ...memory.workspace].slice(0, 5).map((record) => <div className="memory-line" key={record.id}><i />{record.statement}</div>)}{memory.conflicts.length > 0 && <div className="context-warning">存在 {memory.conflicts.length} 个记忆冲突，需要用户选择。</div>}</div></details><details><summary><strong>Template &amp; revision</strong><span>{activeRevision ? "✓" : "＋"}</span></summary><div className="context-content">{activeRevision ? <><div className="context-row"><span>Template</span><strong>{activeRevision.flintSpec.theme} · {activeRevision.flintSpec.themeVersion}</strong></div><div className="context-row"><span>Revision</span><strong>R{activeRevision.revision} · {revisionLabels[activeRevision.status]}</strong></div><div className="context-row"><span>Parent</span><strong>{activeRevision.parentRevisionId ? activeRevision.parentRevisionId.slice(0, 8) : "initial"}</strong></div><div className="context-note">Approved 版本不可修改；编辑会创建新的 Draft Revision。</div></> : <div className="context-empty">首个图表生成后，这里会显示模板版本与 Revision 链。</div>}</div></details><div className="context-divider" /><div className="source-actions"><div className="eyebrow">Data source</div><label className="secondary-button upload-button"><input ref={fileInputRef} type="file" accept=".csv,.xlsx,.xls,.json" disabled={isUploading || isBooting} onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadFile(file); }} />{isUploading ? "处理中…" : "导入文件"}</label><button type="button" className="text-button" onClick={() => void pasteData(sampleCsv, "sales-sample.csv")} disabled={isUploading || isBooting}>使用示例 CSV</button></div></aside>
    </div>
    {showProjectModal && <div className="modal-backdrop" role="presentation" onClick={() => setShowProjectModal(false)}><section className="modal-dialog small-modal" role="dialog" aria-modal="true" aria-labelledby="project-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head lilac-head"><div><div className="eyebrow">NEW CONSULTING PROJECT</div><h2 id="project-modal-title">创建 Project</h2><p>Project 是客户项目、数据、Conversation 和证据版本的长期边界。</p></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowProjectModal(false)}>×</button></div><div className="modal-body"><label className="field-label"><span>PROJECT NAME</span><input autoFocus value={projectName} onChange={(event) => setProjectName(event.target.value)} placeholder="例如：海岚消费洞察" onKeyDown={(event) => { if (event.key === "Enter") void createProject(); }} /></label></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={() => setShowProjectModal(false)}>取消</button><button type="button" className="primary-button" onClick={() => void createProject()} disabled={!projectName.trim()}>创建 Project ↗</button></div></section></div>}
    {showMetricModal && <div className="modal-backdrop" role="presentation" onClick={() => setShowMetricModal(false)}><section className="modal-dialog small-modal" role="dialog" aria-modal="true" aria-labelledby="metric-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head pink-head"><div><div className="eyebrow">METRIC DEFINITION / CONFIRMATION</div><h2 id="metric-modal-title">确认指标口径</h2><p>只有用户确认的 Metric Definition 才能作为 Generation Cycle 输入。</p></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowMetricModal(false)}>×</button></div><div className="modal-body form-grid"><label className="field-label"><span>NAME</span><input value={metricForm.name} onChange={(event) => setMetricForm((current) => ({ ...current, name: event.target.value }))} /></label><label className="field-label"><span>MEANING</span><textarea value={metricForm.meaning} onChange={(event) => setMetricForm((current) => ({ ...current, meaning: event.target.value }))} /></label><label className="field-label"><span>FORMULA</span><input value={metricForm.formula} onChange={(event) => setMetricForm((current) => ({ ...current, formula: event.target.value }))} /></label><div className="form-row"><label className="field-label"><span>UNIT</span><input value={metricForm.unit} onChange={(event) => setMetricForm((current) => ({ ...current, unit: event.target.value }))} /></label><label className="field-label"><span>TIME RULE</span><input value={metricForm.timeRule} onChange={(event) => setMetricForm((current) => ({ ...current, timeRule: event.target.value }))} /></label></div><label className="field-label"><span>FILTER / LIMIT (OPTIONAL)</span><input value={metricForm.filterRule} onChange={(event) => setMetricForm((current) => ({ ...current, filterRule: event.target.value }))} placeholder="例如：仅统计已支付订单" /></label></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={() => setShowMetricModal(false)}>取消</button><button type="button" className="primary-button" onClick={() => void confirmMetric()} disabled={!metricForm.name.trim()}>确认并保存 ↗</button></div></section></div>}
    {showEditor && activeEvidence && activeSpec && <div className="modal-backdrop" role="presentation" onClick={() => setShowEditor(false)}><section className="modal-dialog editor-modal" role="dialog" aria-modal="true" aria-labelledby="editor-modal-title" onClick={(event) => event.stopPropagation()}><div className="modal-head cream-head"><div><div className="eyebrow">CHART ARTIFACT / R{activeRevision?.revision} / NEW DRAFT</div><h2 id="editor-modal-title">编辑图表</h2><p>保存只会创建新的 Chart Revision，不会改变 Snapshot v{selectedAsset?.latestSnapshot?.version ?? "—"} 或历史版本。</p></div><button type="button" className="icon-button" aria-label="关闭" onClick={() => setShowEditor(false)}>×</button></div><div className="editor-body"><div className="editor-preview"><div className="editor-preview-head"><div><strong>{editor.title}</strong><small>{chartTypeName(editor.chartType)} · 新 Draft 预览</small></div><span className="revision-chip">R{(activeRevision?.revision ?? 0) + 1} DRAFT</span></div><InteractiveChart rows={activeRows} spec={{ ...activeSpec, chartSpec: { ...activeSpec.chartSpec, title: editor.title, chartType: editor.chartType, encodings: { x: { field: editor.xField }, y: { field: editor.yField }, ...(editor.seriesField ? { color: { field: editor.seriesField } } : {}) } } }} /><div className="editor-preview-foot"><span>source · snapshot v{selectedAsset?.latestSnapshot?.version ?? "—"}</span><span>lineage · {activeRevision?.fieldLineage.length ?? 0} fields</span></div></div><div className="editor-controls"><div className="control-group"><h3>Chart structure</h3><label className="field-label"><span>CHART TYPE</span><select value={editor.chartType} onChange={(event) => setEditor((current) => ({ ...current, chartType: event.target.value as FlintSpec["chartSpec"]["chartType"] }))}><option>Line Chart</option><option>Bar Chart</option><option>Area Chart</option></select></label><label className="field-label"><span>X AXIS</span><select value={editor.xField} onChange={(event) => setEditor((current) => ({ ...current, xField: event.target.value }))}>{availableFields.map((field) => <option value={field} key={field}>{field}</option>)}</select></label><label className="field-label"><span>Y AXIS</span><select value={editor.yField} onChange={(event) => setEditor((current) => ({ ...current, yField: event.target.value }))}>{availableFields.map((field) => <option value={field} key={field}>{field}</option>)}</select></label><label className="field-label"><span>SERIES / COLOR (OPTIONAL)</span><select value={editor.seriesField} onChange={(event) => setEditor((current) => ({ ...current, seriesField: event.target.value }))}><option value="">不分系列</option>{availableFields.filter((field) => field !== editor.yField).map((field) => <option value={field} key={field}>{field}</option>)}</select></label></div><div className="control-group"><h3>Title &amp; trace</h3><label className="field-label"><span>TITLE</span><input value={editor.title} onChange={(event) => setEditor((current) => ({ ...current, title: event.target.value }))} /></label><div className="logic-note"><strong>{editor.xField !== activeSpec.chartSpec.encodings.x?.field || editor.yField !== activeSpec.chartSpec.encodings.y?.field || editor.seriesField !== (activeSpec.chartSpec.encodings.color?.field ?? "") ? "数据逻辑会重新校验" : "视觉修改会创建新 Revision"}</strong><span>字段或图表类型改变时，系统会保留同一 Snapshot 并重新校验 Flint Spec。</span></div></div></div></div><div className="modal-footer"><p>Chart Revision 是 append-only；Approved 版本保持只读。</p><div><button type="button" className="secondary-button" onClick={() => setShowEditor(false)}>取消</button><button type="button" className="primary-button" onClick={() => void saveEditor()} disabled={isSavingEditor || !editor.title.trim() || !editor.xField || !editor.yField}>{isSavingEditor ? "保存中…" : "保存为新 Revision ↗"}</button></div></div></section></div>}
  </div>;
}
